import{z as B,x as d,o,c as A,q as l,j as t,D as e,d as n,s as r,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"闭包转换与 lambda 提升","description":"","frontmatter":{"title":"闭包转换与 lambda 提升","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/closure-conversion.md","filePath":"cs/closure-conversion.md","lastUpdated":1791063341000}'),p={name:"cs/closure-conversion.md"};function c(m,a,h,u,C,f){const s=d("Mermaid");return o(),A("div",null,[a[2]||(a[2]=l('<h1 id="闭包转换与-lambda-提升" tabindex="-1">闭包转换与 lambda 提升 <a class="header-anchor" href="#闭包转换与-lambda-提升" aria-label="Permalink to &quot;闭包转换与 lambda 提升&quot;">​</a></h1><div class="epigraph"><p>嵌套函数要变成顶层函数加环境参数。闭包转换把自由变量打成记录；lambda lifting 把自由变量变成额外形参。</p><footer>—— 据 Johnsson, Lambda Lifting；Appel, Compiling with Continuations；Peyton Jones 整理</footer></div><p>上一课<a href="/cs/weak-refs-finalizers">弱引用</a> 收束堆。语言特性落地：表面有嵌套 λ。<a href="/cs/lambda-calculus">λ 演算</a> 的自由变量在实现里要有家。缺口是 <strong>closure conversion / lifting</strong>。CPS 下一课。不重写 β。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>λx. ... y ...</code> 的 \\(y\\) 来自外层。机器没有嵌套作用域。转换：<code>λ(env,x). ... env.y</code>，调用处传闭包指针。缺口是<strong>环境表示</strong>（扁平记录、链），不是 GC 弱。<span class="marginnote">直觉类比：闭包是「说明书 + 背包」——代码是说明书，环境记录是背包里装着的函数体要用的外部变量。C 函数指针只有说明书、没有背包，所以表达不了「记住调用处的那个 y」。</span></p><p>提升：把 \\(y\\) 变成参数，调用处传递，适合已知调用点；做成闭包值则必须堆记录。<span class="marginnote">术语翻译 lambda lifting：「把嵌套函数拎到顶层」。它不打包环境，而是把每个自由变量 \\(y\\) 升级成正式参数，调用处逐个实参传进去——签名变长是代价，换来完全不需要堆上的环境记录，适合调用点已知的场合。</span></p><h3 id="闭包不是-c-函数指针" tabindex="-1">闭包不是 C 函数指针 <a class="header-anchor" href="#闭包不是-c-函数指针" aria-label="Permalink to &quot;闭包不是 C 函数指针&quot;">​</a></h3><p>函数指针无环境。带环境的是胖指针 <code>{code, env}</code>。C++ <code>std::function</code>、Rust 闭包各有表示。</p><p><span class="marginnote">Johnsson 1985。Appel CWC。Peyton Jones 实现书。与<a href="/cs/escape-analysis">逃逸</a>：环境未逃逸可栈上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算自由变量。选表示：逃逸则堆闭包。生成顶层函数。调用：间接 <code>code(env, args)</code>。已知闭包+内联则可消间接。</p>',11)),(o(),t(i,null,{default:e(()=>[r(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEST%5B%22%E5%B5%8C%E5%A5%97%20%CE%BB%22%5D%20--%3E%20FV%5B%22%E8%87%AA%E7%94%B1%E5%8F%98%E9%87%8F%22%5D%0A%20%20FV%20--%3E%20ENV%5B%22%E7%8E%AF%E5%A2%83%E8%AE%B0%E5%BD%95%22%5D%0A%20%20ENV%20--%3E%20TOP%5B%22%E9%A1%B6%E5%B1%82%E5%87%BD%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与所有权：环境捕获是移动还是借用，接 Rust 课。与 RC：环境字段要计数。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"链式环境：共享外层，可变捕获麻烦。扁平：复制，可变要盒。不要捕获后还以为外层栈槽活着——悬空，生命周期课已禁。",-1)),(o(),t(i,null,{default:e(()=>[r(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENV%5B%22%E7%8E%AF%E5%A2%83%E8%A1%A8%E7%A4%BA%E4%BA%8C%E9%80%89%E4%B8%80%22%5D%20--%3E%20LINK%5B%22%E9%93%BE%E5%BC%8F%EF%BC%9A%E6%AF%8F%E5%B1%82%E9%97%AD%E5%8C%85%E6%8C%87%E5%90%91%E7%88%B6%E7%8E%AF%E5%A2%83%22%5D%0A%20%20LINK%20--%3E%20LPRO%5B%22%E5%A4%96%E5%B1%82%E7%BB%93%E6%9E%84%E5%85%B1%E4%BA%AB%EF%BC%8C%E4%B8%8D%E5%BF%85%E5%A4%8D%E5%88%B6%22%5D%0A%20%20LINK%20--%3E%20LCON%5B%22%E5%8F%96%E8%BF%9C%E5%A4%84%E7%9A%84%E5%8F%98%E9%87%8F%E8%A6%81%E6%B2%BF%E9%93%BE%E8%B5%B0%E5%A4%9A%E8%B7%B3%22%5D%0A%20%20ENV%20--%3E%20FLAT%5B%22%E6%89%81%E5%B9%B3%EF%BC%9A%E4%B8%80%E4%B8%AA%E8%AE%B0%E5%BD%95%E8%A3%85%E9%BD%90%E5%85%A8%E9%83%A8%E8%87%AA%E7%94%B1%E5%8F%98%E9%87%8F%22%5D%0A%20%20FLAT%20--%3E%20FPRO%5B%22%E5%8F%96%E4%BB%BB%E4%BD%95%E5%8F%98%E9%87%8F%E4%B8%80%E6%AD%A5%E5%88%B0%E4%BD%8D%22%5D%0A%20%20FLAT%20--%3E%20FCON%5B%22%E5%A4%8D%E5%88%B6%E4%BA%86%E5%80%BC%EF%BC%9A%E5%8F%AF%E5%8F%98%E6%8D%95%E8%8E%B7%E5%BF%85%E9%A1%BB%E8%A3%85%E7%9B%92%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">这张图回答「环境到底怎么装」。常见误区：以为捕获变量就自动「共享」。链式环境确实共享外层槽位；扁平环境是复制——可变量因此要先装进盒子。循环里给多个闭包捕获同一个计数器时，拿到的究竟是同一个盒子还是各自的拷贝，就取决于选了哪种表示。</span></p><p>优化：已知函数、无自由变量则退化成函数指针。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CPS。后课默认：嵌套函数降为闭包或提升参数。下一课 CPS 与延续。</p><p>也不把闭包当数学闭包算子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闭包转换：代码+环境；lifting：自由变量变参数。</li><li>表示受逃逸与可变捕获约束。</li><li>无自由变量则退化为函数指针。</li><li>出处：Johnsson；Appel CWC；Peyton Jones。</li></ul>',7))])}const b=B(p,[["render",c]]);export{D as __pageData,b as default};
